import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run, normalize, predict, markdown } from '../tools/validate-agentx.mjs';

// AgentX-shaped results generated by the sizer itself with known efficiencies: calibration must recover them
const TRUTH = { effDecodeBW: 0.55, effDecodeComp: 0.1, stepMs: 8, effPrefill: 0.15 };
function results(hw) {
  return [8, 16, 32, 64, 128].map(conc => {
    const r = { hw, model: 'dsr1-fp8', infmax_model_prefix: 'dsr1', framework: 'sglang', precision: 'fp8', conc, tp: 8, num_gpus: 8, disagg: false, dp_attention: false,
      request_metrics: { tokens: { input: { mean: 90000 }, output_actual: { mean: 450 } }, latency: { tpot: { median: 0.02 }, ttft: { median: 1 }, e2el: { mean: 10 } }, qps: { mean: conc * 0.03 }, throughput: { per_gpu: { output_tput_tps: 1 } } },
      server_metrics: { cache: { gpu_cache_hit_rate: 0.93 } } };
    const x = Object.assign(normalize(r), { numGpus: 8 }), p = predict(x, TRUTH);
    r.request_metrics.latency.tpot.median = p.tpot; r.request_metrics.latency.ttft.median = p.ttft; r.request_metrics.throughput.per_gpu.output_tput_tps = p.outPerGpu;
    return r;
  });
}

test('AgentX results: normalized (in flight from rate × latency, cache hit from the server), scored, and calibrated per GPU', () => {
  const x = normalize(results('b200')[0]);
  assert.equal(x.gpu, 'B200'); assert.equal(x.model, 'deepseek-v3'); assert.equal(Math.round(x.prefixHit), 93); assert.ok(Math.abs(x.inflight - 2.4) < 1e-9);
  const R = run([...results('b200'), ...results('h200')], { fit: true });
  assert.equal(R.scored, 10);
  assert.ok(R.overall.defaults.thr.median > 0.2, 'defaults differ from the planted truth');
  assert.ok(R.overall.calibratedTest.thr.median < 0.02 && R.overall.calibratedTest.tpot.median < 0.02, JSON.stringify(R.overall.calibratedTest));
  assert.deepEqual(R.fits.B200, TRUTH);
  assert.match(markdown(R), /Calibrated per GPU/);
});

test('AgentX results the sizer can\'t score are counted, not guessed', () => {
  const r = results('b200')[0];
  const R = run([{ ...r, infmax_model_prefix: 'kimi-k3', model: 'kimi-k3' }, { ...r, disagg: true }, { ...r, hw: 'tpu7x' }]);
  assert.equal(R.scored, 0);
  assert.deepEqual(Object.keys(R.skipped).sort(), ['GPU tpu7x', 'disaggregated', 'model kimi-k3'].sort());
});
